mapper.select:
SELECT m.id, m.user_id AS userId, m.stall_id AS stallId, m.name, m.description, m.logo_url AS logoUrl, m.business_hours AS businessHours, m.status, c.name AS canteenName, c.type AS canteenType, s.name AS stallName, m.average_score AS averageScore, ( SELECT COUNT(1) FROM dish d WHERE d.merchant_id = m.id AND d.status IN ('ON_SALE', 'SOLD_OUT') ) AS dishCount FROM merchant m INNER JOIN stall s ON s.id = m.stall_id AND s.status = 'OPEN' INNER JOIN canteen c ON c.id = s.canteen_id AND c.status = 'OPEN' WHERE m.apply_status = 'APPROVED' AND m.status = #{status}
AND c.id = #{canteenId}
AND s.id = #{stallId}
ORDER BY m.id ASC
